import{_ as a,o as i,c as t,a3 as s}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"Install A1111 (SD WebUI)","description":"Install AUTOMATIC1111 Stable Diffusion WebUI with --api and LAN listen for MiniTavern image gen.","frontmatter":{"title":"Install A1111 (SD WebUI)","description":"Install AUTOMATIC1111 Stable Diffusion WebUI with --api and LAN listen for MiniTavern image gen.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Install A1111 (SD WebUI) · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Install AUTOMATIC1111 Stable Diffusion WebUI with --api and LAN listen for MiniTavern image gen."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/local/image-gen/a1111"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/local/image-gen/a1111"}]]},"headers":[],"relativePath":"en/local/image-gen/a1111.md","filePath":"en/local/image-gen/a1111.md","lastUpdated":1787224147000}'),n={name:"en/local/image-gen/a1111.md"};function l(o,e,r,d,h,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="install-a1111-sd-webui" tabindex="-1">Install A1111 (SD WebUI) <a class="header-anchor" href="#install-a1111-sd-webui" aria-label="Permalink to &quot;Install A1111 (SD WebUI)&quot;">​</a></h1><p>AUTOMATIC1111 (often <strong>A1111 / SD WebUI</strong>) provides a browser UI and REST API (<code>/sdapi/v1/txt2img</code>).<br> MiniTavern’s <strong>A1111(SD WebUI)</strong> platform talks to this API; <strong>SD.Next</strong> and similar protocols may also work.</p><p>Official repo: <a href="https://github.com/AUTOMATIC1111/stable-diffusion-webui" target="_blank" rel="noreferrer">AUTOMATIC1111/stable-diffusion-webui</a></p><h2 id="hardware-tips" tabindex="-1">Hardware tips <a class="header-anchor" href="#hardware-tips" aria-label="Permalink to &quot;Hardware tips&quot;">​</a></h2><table tabindex="0"><thead><tr><th>VRAM</th><th>Suggestion</th></tr></thead><tbody><tr><td>6GB</td><td>SD 1.5, smaller resolutions</td></tr><tr><td>8GB+</td><td>SDXL more comfortable</td></tr><tr><td>CPU only</td><td>Possible but very slow — path check only</td></tr></tbody></table><h2 id="windows-recommended-starter" tabindex="-1">Windows (recommended starter) <a class="header-anchor" href="#windows-recommended-starter" aria-label="Permalink to &quot;Windows (recommended starter)&quot;">​</a></h2><h3 id="_1-install-dependencies" tabindex="-1">1. Install dependencies <a class="header-anchor" href="#_1-install-dependencies" aria-label="Permalink to &quot;1. Install dependencies&quot;">​</a></h3><ol><li>Install <a href="https://git-scm.com/download/win" target="_blank" rel="noreferrer">Git for Windows</a>.</li><li>Install <a href="https://www.python.org/downloads/" target="_blank" rel="noreferrer">Python 3.10.x</a> (check <strong>Add python.exe to PATH</strong>).</li><li>Prefer a recent <strong>NVIDIA driver</strong> if you have an NVIDIA GPU.</li></ol><h3 id="_2-download-webui" tabindex="-1">2. Download WebUI <a class="header-anchor" href="#_2-download-webui" aria-label="Permalink to &quot;2. Download WebUI&quot;">​</a></h3><p>In a suitable folder (e.g. <code>D:\\AI</code>) open PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git clone https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AUTOMATIC1111</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">diffusion</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webui.git</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd stable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">diffusion</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webui</span></span></code></pre></div><h3 id="_3-first-launch" tabindex="-1">3. First launch <a class="header-anchor" href="#_3-first-launch" aria-label="Permalink to &quot;3. First launch&quot;">​</a></h3><p>Double-click or run in a terminal:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">webui-user.bat</span></span></code></pre></div><p>First run downloads dependencies and base components (takes a while). Then the browser usually opens:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:7860</span></span></code></pre></div><h3 id="_4-enable-api-lan-required-for-phone" tabindex="-1">4. Enable API + LAN (required for phone) <a class="header-anchor" href="#_4-enable-api-lan-required-for-phone" aria-label="Permalink to &quot;4. Enable API + LAN (required for phone)&quot;">​</a></h3><p>Edit <code>webui-user.bat</code> in the same folder. Find <code>COMMANDLINE_ARGS</code> and set e.g.:</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMANDLINE_ARGS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--api --listen</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Role</th></tr></thead><tbody><tr><td><code>--api</code></td><td>Enable <code>/sdapi/v1/*</code> (<strong>required by MiniTavern</strong>)</td></tr><tr><td><code>--listen</code></td><td>Listen on <code>0.0.0.0</code> for LAN devices</td></tr><tr><td><code>--port 7860</code></td><td>Optional; change port in the App too</td></tr></tbody></table><p>Save and re-run <code>webui-user.bat</code>.</p><p>Optional: <code>--api-auth user:password</code> for API auth; if enabled, fill API Key / auth fields in the App image link as the current UI requires.</p><h3 id="_5-verify-the-api" tabindex="-1">5. Verify the API <a class="header-anchor" href="#_5-verify-the-api" aria-label="Permalink to &quot;5. Verify the API&quot;">​</a></h3><p>On the PC browser:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:7860/docs</span></span></code></pre></div><p>Swagger docs mean the API is on. LAN check (replace with PC IP):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.x.x:7860/docs</span></span></code></pre></div><h2 id="macos-linux-summary" tabindex="-1">macOS / Linux summary <a class="header-anchor" href="#macos-linux-summary" aria-label="Permalink to &quot;macOS / Linux summary&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/AUTOMATIC1111/stable-diffusion-webui.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable-diffusion-webui</span></span></code></pre></div><p>Edit <code>webui-user.sh</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMANDLINE_ARGS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--api --listen&quot;</span></span></code></pre></div><p>Then <code>./webui.sh</code>. Apple Silicon works; usually slower than similar NVIDIA.</p><h2 id="download-models-checkpoint" tabindex="-1">Download models (Checkpoint) <a class="header-anchor" href="#download-models-checkpoint" aria-label="Permalink to &quot;Download models (Checkpoint)&quot;">​</a></h2><ol><li>Download <code>.safetensors</code> from <a href="https://civitai.com/" target="_blank" rel="noreferrer">Civitai</a> or <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a>.</li><li>Place in:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stable-diffusion-webui/models/Stable-diffusion/</span></span></code></pre></div><ol start="3"><li>Refresh and pick the model in the WebUI top-left, or restart WebUI.</li></ol><p>Start with a common SD 1.5 or SDXL model; confirm manual generation in WebUI before connecting the App.</p><h2 id="firewall" tabindex="-1">Firewall <a class="header-anchor" href="#firewall" aria-label="Permalink to &quot;Firewall&quot;">​</a></h2><p>Windows: allow Private network access on first listen, or open port <strong>7860</strong>.<br> Phone and PC must share a LAN; guest Wi‑Fi often isolates clients.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./connect-app">Configure in MiniTavern</a> (platform A1111, Base URL = PC LAN address)</li><li>Also: <a href="./index">Image model deploy</a> · in-App <a href="/ultra_guides/en/manual/model-link">Model link · Image gen</a></li></ul>`,41)])])}const g=a(n,[["render",l]]);export{u as __pageData,g as default};
